mkdir -p /tmp/scratch && cat > /tmp/scratch/conv_probe.py <<'EOF'
import json, sys, math
import fsutil
from fsutil.converters import SIZE_UNITS

out = {}
sizes = [0, 1, 1023, 1024, 1536, 2047, 2048, -1, -1024, -1536, 1.5, 1023.9, 1024.5,
         0.4, 0.5, 1234567, 999999999999]
for e in range(0, 111, 5):
    sizes.append(2**e)
for e in range(0, 111):
    sizes.append(2**e)
res = {}
for s in sizes:
    try:
        res[repr(s)] = fsutil.convert_size_bytes_to_string(s)
    except Exception as ex:
        res[repr(s)] = f"{type(ex).__name__}: {ex}"
out["b2s"] = res

strs = []
for u in SIZE_UNITS:
    for amt in ["0", "1", "1.5", "2.5", "1023", "-1", "-2.5", "0.5"]:
        strs.append(f"{amt} {u}")
        strs.append(f"{amt} {u.lower()}")
        strs.append(f"{amt} {u.upper()}")
strs += ["  1 KB  ", "1  KB", "1   KB", "1KB", "1 kb", "2.5 MB", "1 ZB", "1 YB", "1 XB", "", "1", "1 KB extra"]
res2 = {}
for s in strs:
    try:
        v = fsutil.convert_size_string_to_bytes(s)
        res2[repr(s)] = [type(v).__name__, v]
    except Exception as ex:
        res2[repr(s)] = f"{type(ex).__name__}: {ex}"
out["s2b"] = res2

# roundtrip
rt = {}
for s in [0,1,1023,1024,1536,2048,1048576,1572864, 2**30, 2**40, 2**50, 2**60, 2**70, 2**80, 2**90, 2**100]:
    try:
        st = fsutil.convert_size_bytes_to_string(s)
        back = fsutil.convert_size_string_to_bytes(st)
        rt[repr(s)] = [st, back]
    except Exception as ex:
        rt[repr(s)] = f"{type(ex).__name__}: {ex}"
out["rt"] = rt
print(json.dumps(out, indent=0, sort_keys=True))
EOF
